'use client';
import { useEffect, useMemo, useState } from 'react';
import Modal from '@/components/ui/Modal';
import { ArrowUpRight, CheckCircle2, CircleDollarSign, Clock3, IndianRupee, WalletCards } from 'lucide-react';

export default function VendorFinancePage(){
  const [projects,setProjects]=useState([]); const [active,setActive]=useState(null);
  useEffect(()=>{fetch('/api/projects').then(r=>r.json()).then(d=>setProjects(d.projects||[]));},[]);
  const received=projects.reduce((s,p)=>s+(p.amountPaidToVendor||0),0); const pending=projects.reduce((s,p)=>s+(p.amountPendingVendor||0),0); const total=received+pending; const paidRatio=total?Math.round((received/total)*100):0;
  const paidProjects=projects.filter(p=>(p.amountPaidToVendor||0)>0).length; const pendingProjects=projects.filter(p=>(p.amountPendingVendor||0)>0).length;
  const avg=projects.length?Math.round(received/projects.length):0;
  const rows=useMemo(()=>[...projects].sort((a,b)=>new Date(b.eventDate||0)-new Date(a.eventDate||0)),[projects]);
  return <div className="space-y-7">
    <div className="flex flex-col xl:flex-row xl:items-end justify-between gap-5"><div><span className="section-kicker">Business performance</span><h1 className="font-head text-3xl sm:text-4xl mt-1">Finance</h1><p className="text-sm text-secondary mt-2">A clear view of what Pikture Factory has paid, what is pending and how your project earnings are moving.</p></div><div className="rounded-2xl bg-white border border-border px-4 py-3 flex items-center gap-3"><div className="w-9 h-9 rounded-xl bg-gold/10 text-gold flex items-center justify-center"><WalletCards size={17}/></div><div><span className="text-[10px] uppercase tracking-widest text-secondary">Payment status</span><b className="block text-sm">{paidRatio}% settled</b></div></div></div>
    <div className="grid grid-cols-2 xl:grid-cols-4 gap-4"><div className="metric-card"><CheckCircle2 size={17} className="text-success"/><b className="font-head text-2xl block mt-4">₹{received.toLocaleString('en-IN')}</b><span className="text-xs font-semibold">Received</span><span className="text-[11px] text-secondary block mt-1">Across {paidProjects} project{paidProjects===1?'':'s'}</span></div><div className="metric-card"><Clock3 size={17} className="text-warning"/><b className="font-head text-2xl block mt-4">₹{pending.toLocaleString('en-IN')}</b><span className="text-xs font-semibold">Pending</span><span className="text-[11px] text-secondary block mt-1">Across {pendingProjects} project{pendingProjects===1?'':'s'}</span></div><div className="metric-card"><CircleDollarSign size={17} className="text-gold"/><b className="font-head text-2xl block mt-4">₹{total.toLocaleString('en-IN')}</b><span className="text-xs font-semibold">Total project value</span><span className="text-[11px] text-secondary block mt-1">Received + pending</span></div><div className="metric-card"><IndianRupee size={17} className="text-gold"/><b className="font-head text-2xl block mt-4">₹{avg.toLocaleString('en-IN')}</b><span className="text-xs font-semibold">Avg. received / project</span><span className="text-[11px] text-secondary block mt-1">Based on current records</span></div></div>
    <section className="grid xl:grid-cols-[1fr_340px] gap-6"><div className="panel !p-0 overflow-hidden"><div className="px-6 py-5 border-b border-border"><span className="section-kicker">Ledger</span><h2 className="font-head text-2xl mt-1">Project finance</h2></div><div className="divide-y divide-border">{rows.map(p=><button key={p._id} onClick={()=>setActive(p)} className="w-full text-left px-6 py-5 hover:bg-bglight transition-colors"><div className="flex items-center gap-4"><div className="w-10 h-10 rounded-xl bg-bglight text-gold flex items-center justify-center shrink-0"><IndianRupee size={16}/></div><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><span className="text-[10px] font-bold tracking-widest text-gold">{p.projectCode}</span><span className="text-[10px] text-secondary">{p.eventType}</span></div><p className="text-sm font-semibold mt-1 truncate">{p.eventDate?new Date(p.eventDate).toLocaleDateString('en-IN'): 'Date TBD'}</p></div><div className="text-right"><b className="text-sm text-success">₹{(p.amountPaidToVendor||0).toLocaleString('en-IN')}</b><span className="block text-[10px] text-secondary">received</span>{p.amountPendingVendor>0&&<span className="block text-[10px] text-warning mt-1">₹{p.amountPendingVendor.toLocaleString('en-IN')} pending</span>}</div><ArrowUpRight size={15} className="text-secondary"/></div></button>)}{!rows.length&&<div className="py-16 text-center text-sm text-secondary">No finance records yet.</div>}</div></div><div className="panel"><span className="section-kicker">At a glance</span><h3 className="font-head text-2xl mt-1">Settlement health</h3><div className="mt-6 h-3 rounded-full bg-border overflow-hidden"><div className="h-full bg-gold rounded-full" style={{width:`${paidRatio}%`}}/></div><div className="flex justify-between text-xs mt-2"><span>Received</span><b>{paidRatio}%</b></div><div className="mt-7 grid gap-3"><div className="flex justify-between rounded-xl bg-bglight p-3 text-xs"><span>Projects</span><b>{projects.length}</b></div><div className="flex justify-between rounded-xl bg-bglight p-3 text-xs"><span>Received</span><b className="text-success">₹{received.toLocaleString('en-IN')}</b></div><div className="flex justify-between rounded-xl bg-bglight p-3 text-xs"><span>Pending</span><b className="text-warning">₹{pending.toLocaleString('en-IN')}</b></div></div><p className="text-[11px] text-secondary leading-5 mt-6">For payment-specific questions, open the relevant project and message the admin so the conversation stays attached to the correct job.</p></div></section>
    <Modal open={!!active} onClose={()=>setActive(null)} title={active?.projectCode} maxWidth="max-w-md">{active&&<div className="space-y-3 text-sm"><div className="rounded-xl bg-bglight p-4"><span className="text-xs text-secondary">Event</span><b className="block mt-1">{active.eventType}</b></div><div className="flex justify-between rounded-xl border border-border p-4"><span>Amount received</span><b className="text-success">₹{(active.amountPaidToVendor||0).toLocaleString('en-IN')}</b></div><div className="flex justify-between rounded-xl border border-border p-4"><span>Amount pending</span><b className="text-warning">₹{(active.amountPendingVendor||0).toLocaleString('en-IN')}</b></div></div>}</Modal>
  </div>;
}
